28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "postcode")
57	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
58	    private String postcode;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    @Email
67	    private String email;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    /**
94	     * Number of owners belonging to this owner's household (owners sharing the same
95	     * {@code householdId}), including this owner. Derived at request time rather than stored, and
96	     * used to award the {@code GOLD} membership tier to households of three or more members.
97	     */
98	    @Transient
99	    private Integer householdMemberCount;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    public String getTitle() {
105	        return this.title;
106	    }
107	
108	    public void setTitle(String title) {
109	        this.title = title;
110	    }
111	
112	    public String getAddress() {
113	        return this.address;
114	    }
115	
116	    public void setAddress(String address) {
117	        this.address = address;
118	    }
119	
120	    public String getAddressLine1() {
121	        return this.addressLine1;
122	    }
123	
124	    public void setAddressLine1(String addressLine1) {
125	        this.addressLine1 = addressLine1;
126	    }
127	
128	    public String getAddressLine2() {
129	        return this.addressLine2;
130	    }
131	
132	    public void setAddressLine2(String addressLine2) {
133	        this.addressLine2 = addressLine2;
134	    }
135	
136	    public String getCity() {
137	        return this.city;
138	    }
139	
140	    public void setCity(String city) {
141	        this.city = city;
142	    }
143	
144	    public String getPostcode() {
145	        return this.postcode;
146	    }
147	
148	    public void setPostcode(String postcode) {
149	        this.postcode = postcode;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    public void setEmail(String email) {
165	        this.email = email;
166	    }
167	
168	    public LocalDate getRegistrationDate() {
169	        return this.registrationDate;
170	    }
171	
172	    public void setRegistrationDate(LocalDate registrationDate) {
173	        this.registrationDate = registrationDate;
174	    }
175	
176	    public LocalDate getBirthDate() {
177	        return this.birthDate;
178	    }
179	
180	    public void setBirthDate(LocalDate birthDate) {
181	        this.birthDate = birthDate;
182	    }
183	
184	    public String getCustomerCode() {
185	        return this.customerCode;
186	    }
187	
188	    public void setCustomerCode(String customerCode) {
189	        this.customerCode = customerCode;
190	    }
191	
192	    public String getHouseholdId() {
193	        return this.householdId;
194	    }
195	
196	    public void setHouseholdId(String householdId) {
197	        this.householdId = householdId;
198	    }
199	
200	    public Integer getNamesakeCount() {
201	        return this.namesakeCount;
202	    }
203	
204	    public void setNamesakeCount(Integer namesakeCount) {
205	        this.namesakeCount = namesakeCount;
206	    }
207	
208	    public Boolean getBulkSignupWarning() {
209	        return this.bulkSignupWarning;
210	    }
211	
212	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
213	        this.bulkSignupWarning = bulkSignupWarning;
214	    }
215	
216	    public Boolean getPossibleDuplicate() {
217	        return this.possibleDuplicate;
218	    }
219	
220	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
221	        this.possibleDuplicate = possibleDuplicate;
222	    }
223	
224	    public Integer getPossibleDuplicateOf() {
225	        return this.possibleDuplicateOf;
226	    }
227	
228	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
229	        this.possibleDuplicateOf = possibleDuplicateOf;
230	    }
231	
232	    public Integer getHouseholdMemberCount() {
233	        return this.householdMemberCount;
234	    }
235	
236	    public void setHouseholdMemberCount(Integer householdMemberCount) {
237	        this.householdMemberCount = householdMemberCount;
238	    }
239	
240	    protected Set<Pet> getPetsInternal() {
241	        if (this.pets == null) {
242	            this.pets = new HashSet<>();
243	        }
244	        return this.pets;
245	    }
246	
247	    protected void setPetsInternal(Set<Pet> pets) {
248	        this.pets = pets;
249	    }
250	
251	    public List<Pet> getPets() {
252	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
253	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
254	        return Collections.unmodifiableList(sortedPets);
255	    }
256	
257	    public void setPets(List<Pet> pets) {
258	        this.pets = new HashSet<>(pets);
259	    }
260	
261	    public void addPet(Pet pet) {
262	        getPetsInternal().add(pet);
263	        pet.setOwner(this);
264	    }
265	
266	    /**
267	     * Return the Pet with the given name, or null if none found for this Owner.
268	     *
269	     * @param name to test
270	     * @return true if pet name is already in use
271	     */
272	    public Pet getPet(String name) {
273	        return getPet(name, false);
274	    }
275	
276	    /**
277	     * Return the Pet with the given name, or null if none found for this Owner.
278	     *
279	     * @param name to test
280	     * @return true if pet name is already in use
281	     */
282	    public Pet getPet(String name, boolean ignoreNew) {
283	        name = name.toLowerCase();
284	        for (Pet pet : getPetsInternal()) {
285	            if (!ignoreNew || !pet.isNew()) {
286	                String compName = pet.getName();
287	                compName = compName.toLowerCase();
288	                if (compName.equals(name)) {
289	                    return pet;
290	                }
291	            }
292	        }
293	        return null;
294	    }
295	
296	    public Pet getPet(Integer petId) {
297	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
298	    }
299	
300	    @Override
301	    public String toString() {
302	        return new ToStringCreator(this)
303	
304	            .append("id", this.getId())
305	            .append("new", this.isNew())
306	            .append("lastName", this.getLastName())
307	            .append("firstName", this.getFirstName())
308	            .append("address", this.address)
309	            .append("city", this.city)
310	            .append("postcode", this.postcode)
311	            .append("telephone", this.telephone)
312	            .toString();
313	    }
314	}
