17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.HouseholdResolver;
31	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
32	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.Region;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
42	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
43	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
44	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
55	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
176	        flagPossibleDuplicate(owner, ownerFieldsDto);
177	        this.clinicService.saveOwner(owner);
178	        populateHouseholdMemberCount(owner);
179	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
181	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
182	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
183	            owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100));
184	        OwnerDto ownerDto = toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
192	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
193	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
194	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
195	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
196	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
197	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
198	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
199	     *
200	     * @param owner          the newly mapped owner about to be saved
201	     * @param ownerFieldsDto the incoming owner payload
202	     */
203	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
204	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
205	        owner.setNamesakeCount(countNamesakes(owner));
206	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
207	        assignHouseholdId(owner);
208	    }
209	
210	    /**
211	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
212	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
213	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
214	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
215	     * that predate this create; distinct owners therefore always receive distinct customer codes.
216	     *
217	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
218	     * @return the de-duplicated customer code, unique across all existing owners
219	     */
220	    private String deriveUniqueCustomerCode(Owner owner) {
221	        String base = identityKeyResolver.deriveCustomerCode(owner);
222	        Collection<Owner> existing = this.clinicService.findAllOwners();
223	        String candidate = base;
224	        int n = 2;
225	        while (isCustomerCodeInUse(candidate, existing)) {
226	            candidate = base + "-" + n;
227	            n++;
228	        }
229	        return candidate;
230	    }
231	
232	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
233	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
234	    }
235	
236	    /**
237	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
238	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
239	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
240	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
241	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
242	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
243	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
244	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
245	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
246	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
247	     * assigned (see {@link #requireUniqueIdentity}).
248	     *
249	     * @param ownerFieldsDto the incoming owner payload, mutated in place
250	     * @throws MissingOwnerFieldsException if any required field is missing or blank
251	     */
252	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
253	        normalizeAddress(ownerFieldsDto);
254	        validateRequiredFields(ownerFieldsDto);
255	        validatePostcode(ownerFieldsDto);
256	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
257	        ownerFieldsDto.setTelephone(telephone);
258	        requireCityHasCapacity(ownerFieldsDto.getCity());
259	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
260	        ownerFieldsDto.setRegistrationDate(registrationDate);
261	        requireDailyLimitNotReached(registrationDate);
262	        normalizeEmail(ownerFieldsDto);
263	    }
264	
265	    /**
266	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
267	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
268	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
269	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
270	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
271	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
272	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
273	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
274	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
275	     *
276	     * @param ownerFieldsDto the incoming owner payload, mutated in place
277	     */
278	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
279	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
280	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
281	        if (!line1.isEmpty()) {
282	            ownerFieldsDto.setAddressLine1(line1);
283	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
284	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
285	        }
286	        else {
287	            ownerFieldsDto.setAddressLine1(null);
288	            ownerFieldsDto.setAddressLine2(null);
289	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
290	        }
291	    }
292	
293	    /**
294	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
295	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
296	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
297	     * place so the caller can map and save it directly.
298	     *
299	     * @param ownerFieldsDto the incoming owner payload, mutated in place
300	     */
301	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
302	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
303	    }
304	
305	    /**
306	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
307	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
308	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
309	     * later than the current server date is rejected.
310	     *
311	     * @param ownerFieldsDto the incoming owner payload
312	     * @return the effective registration date rolled forward onto a business day
313	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
314	     */
315	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
316	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
317	        if (effective == null) {
318	            effective = LocalDate.now();
319	        }
320	        else if (effective.isAfter(LocalDate.now())) {
321	            throw new FutureRegistrationDateException(
322	                "the registration date must not be later than the current server date");
323	        }
324	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
325	            effective = effective.plusDays(1);
326	        }
327	        return effective;
328	    }
329	
330	    /**
331	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
332	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
333	     * further owner may be created for that day.
334	     *
335	     * @param registrationDate the adjusted business-day registration date of the owner being created
336	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
337	     */
338	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
339	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
340	            throw new DailyOwnerLimitExceededException(
341	                "the maximum number of owners for today has already been reached");
342	        }
343	    }
344	
345	    /**
346	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
347	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
348	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
349	     * warning threshold) so both express the same per-day count in one place.
350	     *
351	     * @param registrationDate the adjusted business-day registration date to count owners for
352	     * @return the number of existing owners registered on that day
353	     */
354	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
355	        return this.clinicService.findAllOwners().stream()
356	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
357	            .count();
358	    }
359	
360	    /**
361	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
362	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
363	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
364	     * reflects only owners that predate it.
365	     *
366	     * @param registrationDate the adjusted business-day registration date of the owner being created
367	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
368	     */
369	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
370	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
371	    }
372	
373	    /**
374	     * Counts how many existing owners already share the given owner's first and last name, compared
375	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
376	     * create; it is zero when the owner's name is unique.
377	     *
378	     * @param owner the newly mapped owner about to be saved
379	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
380	     */
381	    private int countNamesakes(Owner owner) {
382	        String firstName = owner.getFirstName();
383	        String lastName = owner.getLastName();
384	        return (int) this.clinicService.findAllOwners().stream()
385	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
386	                && lastName.equalsIgnoreCase(existing.getLastName()))
387	            .count();
388	    }
389	
390	    /**
391	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
392	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
393	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
394	     *
395	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
396	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
397	     * flat {@code address}.
398	     *
399	     * @param ownerFieldsDto the owner payload to validate
400	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
401	     */
402	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
403	        List<String> missingFields = new ArrayList<>();
404	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
405	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
406	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
407	        requireText(missingFields, "city", ownerFieldsDto.getCity());
408	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
409	        if (!missingFields.isEmpty()) {
410	            throw new MissingOwnerFieldsException(missingFields);
411	        }
412	    }
413	
414	    private void requireText(List<String> missingFields, String fieldName, String value) {
415	        if (value == null || value.isBlank()) {
416	            missingFields.add(fieldName);
417	        }
418	    }
419	
420	    /**
421	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
422	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
423	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
424	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
425	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
426	     *
427	     * @param ownerFieldsDto the incoming owner payload
428	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
429	     */
430	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
431	        String postcode = ownerFieldsDto.getPostcode();
432	        if (postcode == null) {
433	            return;
434	        }
435	        Region region = Region.forCity(ownerFieldsDto.getCity());
436	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
437	            throw new InvalidPostcodeException(
438	                "postcode " + postcode + " is not valid for the city's region " + region.name());
439	        }
440	    }
441	
442	    /**
443	     * Rejects creating an owner whose whole derived {@code identityKey} (see
444	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
445	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
446	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
447	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
448	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
449	     *
450	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
451	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
452	     */
453	    private void requireUniqueIdentity(Owner owner) {
454	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
455	        boolean inUse = this.clinicService.findAllOwners().stream()
456	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
457	        if (inUse) {
458	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
459	        }
460	    }
461	
462	    /**
463	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
464	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
465	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
466	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
467	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
468	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
469	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
470	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
471	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
472	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
473	     *
474	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
475	     * @param ownerFieldsDto the incoming owner payload
476	     */
477	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
478	        owner.setPossibleDuplicate(false);
479	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
480	            return;
481	        }
482	        String postcode = owner.getPostcode();
483	        if (postcode == null || postcode.isBlank()) {
484	            return;
485	        }
486	        String lastName = owner.getLastName();
487	        String telephone = owner.getTelephone();
488	        for (Owner existing : this.clinicService.findAllOwners()) {
489	            if (lastName.equalsIgnoreCase(existing.getLastName())
490	                && postcode.equals(existing.getPostcode())
491	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
492	                owner.setPossibleDuplicate(true);
493	                owner.setPossibleDuplicateOf(existing.getId());
494	                return;
495	            }
496	        }
497	    }
498	
499	    /**
500	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
501	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
502	     *
503	     * @param city the city of the owner being created
504	     * @throws OwnerCityFullException if the city already contains 50 or more owners
505	     */
506	    private void requireCityHasCapacity(String city) {
507	        long cityOwners = this.clinicService.findAllOwners().stream()
508	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
509	            .count();
510	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
511	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
512	        }
513	    }
514	
515	    /**
516	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
517	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
518	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
519	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
520	     * such owners never match one another as a household.
521	     *
522	     * @param owner the newly mapped owner about to be saved
523	     */
524	    private void assignHouseholdId(Owner owner) {
525	        String postcode = owner.getPostcode();
526	        if (postcode == null || postcode.isBlank()) {
527	            owner.setHouseholdId(null);
528	            return;
529	        }
530	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
531	    }
532	
533	    /**
534	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
535	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
536	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
537	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
538	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
539	     * without a postcode) can never be a household duplicate.
540	     *
541	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
542	     * @param ownerFieldsDto the incoming owner payload
543	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
544	     *                                 declare {@code sharesHousehold}
545	     */
546	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
547	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
548	            return;
549	        }
550	        String householdId = owner.getHouseholdId();
551	        if (householdId == null) {
552	            return;
553	        }
554	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
555	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
556	        if (sharedByExisting) {
557	            throw new DuplicateOwnerException("an owner in the same household already exists");
558	        }
559	    }
560	
561	    /**
562	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
563	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
564	     * household is counted as a household of one.
565	     *
566	     * @param owner the owner whose household size should be resolved
567	     */
568	    private void populateHouseholdMemberCount(Owner owner) {
569	        String householdId = owner.getHouseholdId();
570	        if (householdId == null) {
571	            owner.setHouseholdMemberCount(1);
572	            return;
573	        }
574	        long members = this.clinicService.findAllOwners().stream()
575	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
576	            .count();
577	        owner.setHouseholdMemberCount((int) members);
578	    }
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Override
582	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
583	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
584	        if (currentOwner == null) {
585	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
586	        }
587	        validatePostcode(ownerFieldsDto);
588	        currentOwner.setAddress(ownerFieldsDto.getAddress());
589	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
590	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
591	        currentOwner.setCity(ownerFieldsDto.getCity());
592	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
593	        currentOwner.setLastName(ownerFieldsDto.getLastName());
594	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
595	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
596	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
597	        this.clinicService.saveOwner(currentOwner);
598	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
599	    }
600	
601	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
602	    @Transactional
603	    @Override
604	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
605	        Owner owner = this.clinicService.findOwnerById(ownerId);
606	        if (owner == null) {
607	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	        }
609	        this.clinicService.deleteOwner(owner);
610	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
611	    }
612	
613	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
614	    @Override
615	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
616	        Owner owner = this.clinicService.findOwnerById(ownerId);
617	        if (owner == null) {
618	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
619	        }
620	        HttpHeaders headers = new HttpHeaders();
621	        Pet pet = petMapper.toPet(petFieldsDto);
622	        owner.setId(ownerId);
623	        pet.setOwner(owner);
624	        pet.getType().setName(null);
625	        this.clinicService.savePet(pet);
626	        PetDto petDto = petMapper.toPetDto(pet);
627	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
628	            .buildAndExpand(pet.getId()).toUri());
629	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
635	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
636	        if (currentOwner != null) {
637	            Pet currentPet = this.clinicService.findPetById(petId);
638	            if (currentPet != null) {
639	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
640	                currentPet.setName(petFieldsDto.getName());
641	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
642	                this.clinicService.savePet(currentPet);
643	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
644	            }
645	        }
646	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
647	    }
648	
649	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
650	    @Override
651	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
652	        HttpHeaders headers = new HttpHeaders();
653	        Visit visit = visitMapper.toVisit(visitFieldsDto);
654	        Pet pet = new Pet();
655	        pet.setId(petId);
656	        visit.setPet(pet);
657	        this.clinicService.saveVisit(visit);
658	        VisitDto visitDto = visitMapper.toVisitDto(visit);
659	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
660	            .buildAndExpand(visit.getId()).toUri());
661	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
662	    }
663	
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Override
667	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
668	        Owner owner = this.clinicService.findOwnerById(ownerId);
669	        if (owner != null) {
670	            Pet pet = owner.getPet(petId);
671	            if (pet != null) {
672	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
673	            }
674	        }
675	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
676	    }
677	}
